pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1);
        address receiver = address(0x2);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        c.sendTo(receiver, 1);
        // Now owner calls; should succeed in reference (owner allowed), revert in buggy (owner forbidden)
        bool ok;
        try c.sendTo(receiver, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

